//! NVIDIA's video decoder's declarations (`cuviddec.h`, `nvcuvid.h` of the
//! Video Codec SDK, generated by bindgen in the `nvidia-video-codec-sdk`
//! crate, MIT): its types only. Nothing is linked: olo-video opens
//! `libnvcuvid.so.1` and `libcuda.so.1` at run time (`nvdec.rs`), so Olo
//! builds and starts without them.
#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals, dead_code, unused_imports, unpredictable_function_pointer_comparisons, clippy::all)]

/// CUDA's stream (the only CUDA type these use).
pub type CUstream = *mut core::ffi::c_void;

pub mod cuviddec {
    use super::CUstream;
    include!("cuviddec.rs");
}

pub mod nvcuvid {
    use super::CUstream;
    use super::cuviddec::*;
    include!("nvcuvid.rs");
}
